// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());

        bool ok;
        vm.prank(caller);
        try c.burn(amount) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
